// 截图打码助手 v1.0
// 用于 SillyTavern 截图 repo 时打码 user/char 名字、自定义关键词
console.log('[截图打码] v1.8 启动');

const TOP = window.top;
const TOP_DOC = TOP.document;
const LS_KEY = 'mask_helper_config';

const ST_DATA_KEY = 'mask_helper_manual_data';
const MANUAL_BACKUP_KEY = 'mask_helper_manual_backup_v18';
const manualIO = {
  ready: false, busy: false, dirty: false, base: [], last: '',
  core: null, timer: null, notified: '', disposed: false, startedAt: Date.now(),
};
const copyManual = value => JSON.parse(JSON.stringify(value));
function validManual(value) {
  return Array.isArray(value) && value.every(x => x && typeof x.word === 'string'
    && typeof x.on === 'boolean' && typeof x.style === 'string' && typeof x.custom === 'string');
}
function manualNotice(message) {
  console.warn('[截图打码] ' + message);
  if (manualIO.notified === message) return;
  manualIO.notified = message;
  if (TOP.toastr?.warning) TOP.toastr.warning(message, '手动映射保存');
  else TOP.alert(message);
}
function loadConfig() {
  const def = defaultConfig();
  let cfg;
  try { cfg = JSON.parse(TOP.localStorage.getItem(LS_KEY) || 'null'); }
  catch (e) { console.warn('[截图打码] 本机配置读取失败', e); }
  const merged = cfg ? Object.assign(def, cfg, {
    auto: Object.assign(def.auto, cfg.auto || {}),
  }) : def;
  if (!validManual(merged.manual)) merged.manual = [];
  return merged;
}
function backupManual() {
  try {
    TOP.localStorage.setItem(MANUAL_BACKUP_KEY, JSON.stringify({
      manual: S.config.manual, base: manualIO.base, pending: manualIO.dirty,
    }));
  } catch (e) { manualNotice('本机备份失败；请等酒馆保存完成后再刷新。'); }
}
function refreshManualUI() {
  renderAutoRows(); renderManualList(); reapply();
}
// 只合并本机实际改动；启动前编辑不会删除后端尚未读取的词。
function mergeManual(remote, base, local) {
  const result = copyManual(remote);
  for (const old of base) {
    if (!local.some(x => x.word === old.word)) {
      const index = result.findIndex(x => x.word === old.word);
      if (index >= 0) result.splice(index, 1);
    }
  }
  for (const item of local) {
    const old = base.find(x => x.word === item.word);
    if (!old || JSON.stringify(old) !== JSON.stringify(item)) {
      const index = result.findIndex(x => x.word === item.word);
      if (index >= 0) result[index] = copyManual(item);
      else result.push(copyManual(item));
    }
  }
  return result;
}
async function getManualContext() {
  if (!manualIO.core) {
    // 必须在顶层窗口导入，复用酒馆的模块实例，避免 iframe 中重复运行 script.js。
    manualIO.core = await TOP.Function('url', 'return import(url)')(
      new URL('script.js', TOP.document.baseURI).href);
  }
  const ctx = TOP.SillyTavern?.getContext?.();
  if (!manualIO.core.settingsReady || !ctx?.extensionSettings) return null;
  if (typeof ctx.saveSettingsDebounced !== 'function' || typeof ctx.getRequestHeaders !== 'function') {
    throw new Error('酒馆保存接口不可用');
  }
  return ctx;
}
async function readManualBackend(ctx) {
  const controller = new TOP.AbortController();
  const timer = setTimeout(() => controller.abort(), 10000);
  try {
    const response = await TOP.fetch(new URL('api/settings/get', TOP.document.baseURI).href, {
      method: 'POST', headers: ctx.getRequestHeaders(), body: '{}',
      credentials: 'same-origin', cache: 'no-store', signal: controller.signal,
    });
    if (!response.ok) throw new Error('读取酒馆设置失败：HTTP ' + response.status);
    const data = await response.json();
    const settings = typeof data.settings === 'string' ? JSON.parse(data.settings) : data.settings;
    if (!settings || typeof settings !== 'object') throw new Error('酒馆设置响应格式错误');
    const entry = settings.extension_settings?.[ST_DATA_KEY];
    if (entry !== undefined && !validManual(entry?.manual)) throw new Error('酒馆映射格式异常，未覆盖现有数据');
    return entry;
  } finally { clearTimeout(timer); }
}
function retryManual(ms = 5000) {
  clearTimeout(manualIO.timer);
  if (!manualIO.disposed) manualIO.timer = setTimeout(() => { void syncManual(); }, ms);
}
async function syncManual() {
  if (manualIO.busy || manualIO.disposed) return;
  manualIO.busy = true;
  try {
    const ctx = await getManualContext();
    if (!ctx) {
      if (Date.now() - manualIO.startedAt > 15000) manualNotice('正在等待酒馆用户设置加载，映射已保留，尚未写入后端。');
      retryManual(1000); return;
    }
    const entry = await readManualBackend(ctx);
    const remote = entry?.manual || [];
    const local = copyManual(S.config.manual);
    let target;
    if (!manualIO.ready) {
      target = manualIO.dirty ? mergeManual(remote, manualIO.base, local) : copyManual(remote);
      // V1.6/V1.7 的残存本机名单只在旧版后端尚无有效名单时迁移。
      if (!manualIO.dirty && !remote.length && entry?.schemaVersion !== 18 && local.length) target = local;
      manualIO.ready = true;
    } else {
      target = manualIO.dirty ? mergeManual(remote, manualIO.base, local) : copyManual(remote);
    }
    manualIO.base = copyManual(remote);
    S.config.manual = target;
    manualIO.last = JSON.stringify(target);
    manualIO.dirty = JSON.stringify(target) !== JSON.stringify(remote);
    ctx.extensionSettings[ST_DATA_KEY] = { ...(entry || {}), manual: copyManual(target), schemaVersion: 18 };
    refreshManualUI();
    backupManual();
    if (!manualIO.dirty) return;
    const snapshot = copyManual(target);
    // 用酒馆原生保存器，保留其他用户设置；不能把调度保存当作成功落盘。
    ctx.saveSettingsDebounced();
    let verified = false;
    for (let attempt = 0; attempt < 8; attempt++) {
      await new Promise(resolve => setTimeout(resolve, 750));
      const saved = await readManualBackend(ctx);
      if (JSON.stringify(saved?.manual) === JSON.stringify(snapshot) && saved?.schemaVersion === 18) {
        verified = true; break;
      }
    }
    if (!verified) throw new Error('后端未确认保存');
    manualIO.base = snapshot;
    manualIO.dirty = JSON.stringify(S.config.manual) !== JSON.stringify(snapshot);
    backupManual();
    manualIO.notified = '';
    if (!manualIO.dirty) TOP.toastr?.success?.('手动映射已保存到酒馆。', '截图打码');
    if (manualIO.dirty) retryManual(100);
  } catch (e) {
    console.error('[截图打码] 手动映射持久化失败', e);
    manualNotice('手动映射尚未保存到酒馆，现有映射已保留，将自动重试。请等保存完成后再关闭页面。');
    backupManual();
    retryManual();
  } finally { manualIO.busy = false; }
}
function saveManualToST() {
  const serialized = JSON.stringify(S.config.manual);
  if (serialized !== manualIO.last) {
    manualIO.last = serialized;
    manualIO.dirty = true;
    backupManual();
    retryManual(100);
  }
}
function saveConfig() {
  try {
    // 保留恢复副本；跨设备读取仍以后端为准。
    TOP.localStorage.setItem(LS_KEY, JSON.stringify(S.config));
  } catch (e) { console.warn('[截图打码] UI 偏好保存失败', e); }
  saveManualToST();
}
function startManualPersistence() {
  manualIO.base = copyManual(S.config.manual);
  try {
    const backup = JSON.parse(TOP.localStorage.getItem(MANUAL_BACKUP_KEY) || 'null');
    if (backup && validManual(backup.manual) && validManual(backup.base)) {
      S.config.manual = copyManual(backup.manual);
      manualIO.base = copyManual(backup.base);
      manualIO.dirty = backup.pending === true;
    }
  } catch (e) { console.warn('[截图打码] 备份读取失败', e); }
  manualIO.last = JSON.stringify(S.config.manual);
  refreshManualUI();
  void syncManual();
  const onFocus = () => { void syncManual(); };
  const onVisibility = () => { if (!TOP_DOC.hidden) onFocus(); };
  const onUnload = event => {
    if (!manualIO.dirty) return;
    backupManual(); event.preventDefault(); event.returnValue = '';
  };
  TOP.addEventListener('focus', onFocus);
  TOP.addEventListener('online', onFocus);
  TOP_DOC.addEventListener('visibilitychange', onVisibility);
  TOP.addEventListener('beforeunload', onUnload);
  window.addEventListener('pagehide', () => {
    manualIO.disposed = true; clearTimeout(manualIO.timer);
    TOP.removeEventListener('focus', onFocus);
    TOP.removeEventListener('online', onFocus);
    TOP_DOC.removeEventListener('visibilitychange', onVisibility);
    TOP.removeEventListener('beforeunload', onUnload);
  }, { once: true });
}


if (!window._maskS) {
  window._maskS = {
    config: loadConfig(),
    masking: false,
    autoNames: { user: '', char: '' },
  };
}
const S = window._maskS;
S.config.bubbleSize = Math.max(32, Math.min(72, Number(S.config.bubbleSize) || 42));
const BUBBLE_IMAGE = 'data:image/png;base64,';
const BUBBLE_IMAGE_MASKING = 'data:image/png;base64,';

// ──────────────── 配置 ────────────────
function defaultConfig() {
  return {
    posX: null, posY: null,
    theme: 'dark',
    hidden: false,
    bubbleSize: 42,
    // 自动检测名字：是否打码、用什么样式
    auto: {
      user: { on: true, style: 'blur', custom: '' },
      char: { on: true, style: 'blur', custom: '' },
    },
    // 手动添加的名字/关键词
    manual: [],  // [{ word, on, style, custom }]
    // 默认样式
    defaultStyle: 'blur',
    defaultCustom: '🌸',
  };
}
// ──────────────── 图标 ────────────────
const ICONS = {
  mask: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7z"/><path d="M2 12s3-7 10-7" stroke-dasharray="2 2"/><line x1="4" y1="20" x2="20" y2="4"/></svg>',
  close: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>',
  trash: '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6"/></svg>',
  plus: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>',
  sun: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="4"/><line x1="12" y1="2" x2="12" y2="5"/><line x1="12" y1="19" x2="12" y2="22"/><line x1="2" y1="12" x2="5" y2="12"/><line x1="19" y1="12" x2="22" y2="12"/><line x1="4.93" y1="4.93" x2="7.05" y2="7.05"/><line x1="16.95" y1="16.95" x2="19.07" y2="19.07"/><line x1="4.93" y1="19.07" x2="7.05" y2="16.95"/><line x1="16.95" y1="7.05" x2="19.07" y2="4.93"/></svg>',
  moon: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>',
  search: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>',
  refresh: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg>',
};

// 打码样式枚举
const MASK_STYLES = [
  { id: 'blur',   name: '🌫️ 模糊' },
  { id: 'black',  name: '⬛ 涂黑' },
  { id: 'mosaic', name: '🟪 马赛克' },
  { id: 'text',   name: '🅰️ 文字' },
  { id: 'emoji',  name: '😀 Emoji' },
];

// ──────────────── 工具 ────────────────
function g(id) { return TOP_DOC.getElementById(id); }
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function escRegex(s){return String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}

// 获取当前 user / char 名
// 参考"工具-一键打码"脚本的方式：直接读 SillyTavern.name1/name2 + TavernHelper.getCharData
function refreshAutoNames() {
  let user = '', char = '';

  // USER 名
  try {
    if (typeof TOP.SillyTavern?.name1 === 'string') user = TOP.SillyTavern.name1.trim();
  } catch(e) {}
  if (!user) {
    try {
      const ctx = TOP.SillyTavern?.getContext?.();
      if (ctx?.name1) user = String(ctx.name1).trim();
    } catch(e) {}
  }

  // CHAR 名
  try {
    const TH = TOP.TavernHelper;
    if (TH?.getCharData) {
      const cd = TH.getCharData('current');
      if (cd?.name) char = String(cd.name).trim();
    }
  } catch(e) {}
  if (!char) {
    try {
      if (typeof TOP.SillyTavern?.name2 === 'string') char = TOP.SillyTavern.name2.trim();
    } catch(e) {}
  }

  S.autoNames.user = user;
  S.autoNames.char = char;
}

// 拼出当前所有要打码的目标
function collectTargets() {
  refreshAutoNames();
  const remembered = S.config.manual || [];
  const list = [];
  // 保存过的词优先沿用自己的开关、样式和替换内容，跨聊天有效。
  ['user', 'char'].forEach(key => {
    const word = S.autoNames[key];
    if (!word) return;
    const saved = remembered.find(it => it.word === word);
    if (saved) {
      if (saved.on) list.push({ ...saved });
    } else if (S.config.auto[key].on) {
      list.push({ word, ...S.config.auto[key] });
    }
  });
  remembered.forEach(it => {
    if (it.on && it.word && !list.some(x => x.word === it.word)) list.push(it);
  });
  list.sort((a, b) => b.word.length - a.word.length);
  return list;
}
function rememberAutoName(key) {
  refreshAutoNames();
  const word = S.autoNames[key];
  if (!word) return;
  const items = S.config.manual || (S.config.manual = []);
  const saved = items.find(it => it.word === word);
  if (saved) {
    // 重复点击只读取已有记录，避免覆盖之前手动修改过的设置。
    renderAutoRows(); return;
  }
  items.push({ word, on: S.config.auto[key].on, style: S.config.auto[key].style,
    custom: S.config.auto[key].custom });
  saveConfig(); renderAutoRows(); renderManualList(); reapply();
}

// ──────────────── 打码渲染 ────────────────
// 思路：对消息容器和发送者名字容器的文本节点做替换，把目标包成 <span class="mh-mask" data-style="...">原文</span>
// 不修改 DOM 之外的实际消息内容，只在显示层加 span，关闭打码时移除 span

function maskTextNode(node, targets) {
  const text = node.nodeValue;
  if (!text || !text.trim()) return false;
  const pattern = targets.map(t => escRegex(t.word)).join('|');
  if (!pattern) return false;
  const re = new RegExp(pattern, 'g');
  if (!re.test(text)) return false;
  re.lastIndex = 0;

  const frag = TOP_DOC.createDocumentFragment();
  let lastIdx = 0;
  let m;
  while ((m = re.exec(text)) !== null) {
    if (m.index > lastIdx) {
      frag.appendChild(TOP_DOC.createTextNode(text.slice(lastIdx, m.index)));
    }
    const matched = m[0];
    // targets 已按长度倒序，先找到完全相等的最长 word
    const t = targets.find(x => x.word === matched);
    const span = TOP_DOC.createElement('span');
    span.className = 'mh-mask';
    span.dataset.style = t?.style || 'blur';
    if (t && (t.style === 'text' || t.style === 'emoji')) {
      span.dataset.original = matched;
      span.textContent = t.custom || (t.style === 'emoji' ? '🌸' : 'XX');
    } else {
      span.textContent = matched;
    }
    frag.appendChild(span);
    lastIdx = m.index + matched.length;
  }
  if (lastIdx < text.length) {
    frag.appendChild(TOP_DOC.createTextNode(text.slice(lastIdx)));
  }
  node.parentNode.replaceChild(frag, node);
  return true;
}

function walkAndMask(root, targets) {
  if (!root || !targets.length) return;
  // 只处理消息文本区 + 发送者名字区，避免误伤 UI
  const targetsEls = root.querySelectorAll('.mes_text, .ch_name, .name_text, .mes .timestamp, .mes_block .ch_name');
  targetsEls.forEach(el => {
    // 已经处理过的跳过
    if (el.dataset.mhMasked === '1') return;
    walkTextNodes(el, targets);
    el.dataset.mhMasked = '1';
  });
}

function walkTextNodes(el, targets) {
  // 收集所有文本节点（避开 .mh-mask 内部）
  const nodes = [];
  const walker = TOP_DOC.createTreeWalker(el, NodeFilter.SHOW_TEXT, {
    acceptNode(n) {
      if (n.parentNode && n.parentNode.closest('.mh-mask')) return NodeFilter.FILTER_REJECT;
      if (n.parentNode && (n.parentNode.tagName === 'SCRIPT' || n.parentNode.tagName === 'STYLE')) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });
  let n;
  while ((n = walker.nextNode())) nodes.push(n);
  nodes.forEach(node => maskTextNode(node, targets));
}

function clearMasks(root) {
  if (!root) root = TOP_DOC;
  root.querySelectorAll('.mh-mask').forEach(span => {
    const original = span.dataset.original || span.textContent;
    const text = TOP_DOC.createTextNode(original);
    span.parentNode.replaceChild(text, span);
  });
  root.querySelectorAll('[data-mh-masked="1"]').forEach(el => {
    delete el.dataset.mhMasked;
    // 合并相邻 text node
    el.normalize();
  });
}

function applyMasksAll() {
  const chat = TOP_DOC.getElementById('chat');
  if (!chat) return;
  const targets = collectTargets();
  if (!targets.length) { updateStats(); return; }
  window._mhApplying = true;
  try {
    walkAndMask(chat, targets);
  } finally {
    // 等下一个 microtask 再放开，避免 observer 看到自己的改动
    setTimeout(() => { window._mhApplying = false; }, 50);
  }
  updateStats();
}

function reapply() {
  clearMasks(TOP_DOC.getElementById('chat'));
  if (S.masking) applyMasksAll();
  updateStats();
}

// ──────────────── 截图模式开关 ────────────────
function setMasking(on) {
  S.masking = !!on;
  const bubbleImg = TOP_DOC.querySelector('#mh-bubble .mh-bubble-img');
  if (bubbleImg) bubbleImg.src = S.masking ? BUBBLE_IMAGE_MASKING : BUBBLE_IMAGE;
  const root = TOP_DOC.getElementById('mh-root');
  if (root) root.classList.toggle('masking', S.masking);
  const btn = g('mh-toggle-big');
  if (btn) {
    btn.classList.toggle('on', S.masking);
    btn.textContent = S.masking ? '🛡️ 截图模式已开启' : '截图模式';
  }
  if (S.masking) applyMasksAll();
  else clearMasks(TOP_DOC.getElementById('chat'));
  updateStats();
}

// ──────────────── UI ────────────────
function mountUI() {
  if (TOP_DOC.getElementById('mh-root')) return;

  if (!TOP_DOC.getElementById('mh-style')) {
    const style = TOP_DOC.createElement('style');
    style.id = 'mh-style';
    style.textContent = CSS_TEMPLATE;
    TOP_DOC.head.appendChild(style);
  }

  const root = TOP_DOC.createElement('div');
  root.id = 'mh-root';
  root.setAttribute('data-theme', S.config.theme || 'dark');
  if (S.config.hidden) root.classList.add('hidden');
  if (S.masking) root.classList.add('masking');

  root.style.setProperty('--mh-size', S.config.bubbleSize + 'px');
  const bubbleSize = S.config.bubbleSize;
  if (S.config.posX !== null && S.config.posY !== null) {
    root.style.left = clamp(S.config.posX, 0, TOP.innerWidth - bubbleSize) + 'px';
    root.style.top = clamp(S.config.posY, 0, TOP.innerHeight - bubbleSize) + 'px';
  } else {
    root.style.left = Math.round((TOP.innerWidth - bubbleSize) / 2) + 'px';
    root.style.top = Math.round((TOP.innerHeight - bubbleSize) / 2) + 'px';
  }

  root.innerHTML = `
    <div id="mh-panel" class="above right">
      <div class="mh-title">
        <span class="mh-title-icon">${ICONS.mask}<span>截图打码</span></span>
        <span id="mh-x" class="mh-close">${ICONS.close}</span>
      </div>
      <div class="mh-tabs">
        <div class="mh-tab on" data-page="main">截图模式</div>
        <div class="mh-tab" data-page="names">名字管理</div>
        <div class="mh-tab" data-page="setting">设置</div>
      </div>

      <!-- Tab 1 截图模式 -->
      <div class="mh-page on" data-page="main">
        <button id="mh-toggle-big" class="mh-big-btn">截图模式</button>
        <div class="mh-stats" id="mh-stats">未启用</div>
        <div class="mh-hint">
          点击上方按钮开启 / 关闭打码<br>
          开启后匹配的名字 / 关键词会被覆盖
        </div>
      </div>

      <!-- Tab 2 名字管理 -->
      <div class="mh-page" data-page="names">
        <div class="mh-section">
          <div class="mh-section-title">
            <span>自动检测</span>
            <button class="mh-mini-btn" id="mh-refresh-btn">${ICONS.refresh}刷新</button>
          </div>
