// ──────────────── 事件 ────────────────
function bindEvents(root) {
  const panel = g('mh-panel'), bubble = g('mh-bubble');

  // Tab 切换
  TOP_DOC.querySelectorAll('.mh-tab').forEach(t => {
    t.addEventListener('click', () => {
      TOP_DOC.querySelectorAll('.mh-tab').forEach(x => x.classList.remove('on'));
      t.classList.add('on');
      TOP_DOC.querySelectorAll('.mh-page').forEach(p => p.classList.remove('on'));
      TOP_DOC.querySelector(`.mh-page[data-page="${t.dataset.page}"]`).classList.add('on');
    });
  });

  g('mh-x').addEventListener('click', () => panel.classList.remove('open'));

  // 截图模式大按钮
  g('mh-toggle-big').addEventListener('click', () => setMasking(!S.masking));

  // 刷新自动检测
  g('mh-refresh-btn').addEventListener('click', () => {
    renderAutoRows();
    reapply();
  });

  // 手动添加
  const addInp = g('mh-add-input');
  const doAdd = () => {
    const v = addInp.value.trim();
    if (!v) return;
    if ((S.config.manual || []).find(x => x.word === v)) {
      addInp.value = ''; return;
    }
    S.config.manual.push({
      word: v, on: true,
      style: S.config.defaultStyle,
      custom: S.config.defaultCustom,
    });
    saveConfig();
    addInp.value = '';
    renderManualList();
    reapply();
  };
  g('mh-add-btn').addEventListener('click', doAdd);
  addInp.addEventListener('keydown', e => { if (e.key === 'Enter') doAdd(); });

  // 主题
  TOP_DOC.querySelectorAll('.mh-theme-opt').forEach(o => {
    o.classList.toggle('on', o.dataset.theme === (S.config.theme || 'dark'));
    o.addEventListener('click', () => applyTheme(o.dataset.theme));
  });

  // 默认样式
  g('mh-default-style').addEventListener('change', e => {
    S.config.defaultStyle = e.target.value; saveConfig();
  });
  g('mh-default-custom').addEventListener('input', e => {
    S.config.defaultCustom = e.target.value; saveConfig();
  });

  g('mh-bubble-size').addEventListener('input', e => {
    S.config.bubbleSize = Number(e.target.value);
    root.style.setProperty('--mh-size', S.config.bubbleSize + 'px');
    g('mh-bubble-size-value').textContent = S.config.bubbleSize + 'px';
    root.style.left = clamp(root.getBoundingClientRect().left, 0, Math.max(0, TOP.innerWidth - S.config.bubbleSize)) + 'px';
    root.style.top = clamp(root.getBoundingClientRect().top, 0, Math.max(0, TOP.innerHeight - S.config.bubbleSize)) + 'px';
    S.config.posX = root.getBoundingClientRect().left;
    S.config.posY = root.getBoundingClientRect().top;
    saveConfig();
  });

  // 气泡：点击 = 切换面板；长按 = 隐藏
  setupBubble(root, bubble, panel);
}

function setupBubble(root, bubble, panel) {
  // 状态机：idle → pressing → (moving | longpressed) → idle
  // pressing: 按下还没决定是 click/drag/longpress
  // moving:   已经移动超过阈值，进入拖动
  // longpressed: 长按定时器触发，已经隐藏，等抬起就重置
  let state = 'idle';
  let sx = 0, sy = 0, ox = 0, oy = 0;
  let pressTimer = null;
  const LONG_PRESS_MS = 600;
  const MOVE_THRESHOLD = 5;

  const clearTimer = () => { if (pressTimer) { clearTimeout(pressTimer); pressTimer = null; } };

  const onStart = (cx, cy) => {
    state = 'pressing';
    const r = root.getBoundingClientRect();
    sx = cx; sy = cy; ox = r.left; oy = r.top;
    bubble.classList.add('dragging');
    pressTimer = setTimeout(() => {
      if (state === 'pressing') {
        state = 'longpressed';
        bubble.classList.remove('dragging');
        setHidden(true);
      }
      pressTimer = null;
    }, LONG_PRESS_MS);
  };

  const onMove = (cx, cy) => {
    if (state !== 'pressing' && state !== 'moving') return;
    const dx = cx - sx, dy = cy - sy;
    if (state === 'pressing' && Math.abs(dx) + Math.abs(dy) > MOVE_THRESHOLD) {
      state = 'moving';
      clearTimer();
    }
    if (state !== 'moving') return;
    const winW = TOP.innerWidth, winH = TOP.innerHeight;
    const newX = clamp(ox + dx, 0, Math.max(0, winW - S.config.bubbleSize));
    const newY = clamp(oy + dy, 0, Math.max(0, winH - S.config.bubbleSize));
    root.style.left = newX + 'px';
    root.style.top = newY + 'px';
    panel.classList.toggle('above', newY > winH / 2);
    panel.classList.toggle('below', newY <= winH / 2);
    panel.classList.toggle('right', newX > winW / 2);
    panel.classList.toggle('left', newX <= winW / 2);
  };

  const onEnd = () => {
    clearTimer();
    bubble.classList.remove('dragging');
    const prevState = state;
    state = 'idle';
    if (prevState === 'pressing') {
      // 短按 → 切换面板
      panel.classList.toggle('open');
    } else if (prevState === 'moving') {
      const r = root.getBoundingClientRect();
      S.config.posX = r.left; S.config.posY = r.top;
      saveConfig();
    }
    // longpressed: 已经处理过，啥也不做
  };

  bubble.addEventListener('mousedown', e => { onStart(e.clientX, e.clientY); e.preventDefault(); });
  TOP_DOC.addEventListener('mousemove', e => onMove(e.clientX, e.clientY));
  TOP_DOC.addEventListener('mouseup', onEnd);
  bubble.addEventListener('touchstart', e => { e.preventDefault(); const t = e.touches[0]; onStart(t.clientX, t.clientY); }, { passive: false });
  TOP_DOC.addEventListener('touchmove', e => { if (state === 'idle') return; const t = e.touches[0]; onMove(t.clientX, t.clientY); }, { passive: true });
  TOP_DOC.addEventListener('touchend', e => { if (state !== 'idle') { e.preventDefault(); onEnd(); } }, { passive: false });
  TOP_DOC.addEventListener('touchcancel', () => { clearTimer(); state = 'idle'; bubble.classList.remove('dragging'); });
}

function applyTheme(theme) {
  const root = TOP_DOC.getElementById('mh-root');
  if (root) root.setAttribute('data-theme', theme);
  S.config.theme = theme;
  saveConfig();
  TOP_DOC.querySelectorAll('.mh-theme-opt').forEach(o => {
    o.classList.toggle('on', o.dataset.theme === theme);
  });
}

function setHidden(hide) {
  const root = TOP_DOC.getElementById('mh-root');
  if (root) root.classList.toggle('hidden', hide);
  S.config.hidden = hide;
  saveConfig();
  const wandText = TOP_DOC.getElementById('mh-wand-toggle-text');
