// ──────────────── 魔法棒菜单注入 ────────────────
function injectWandMenu() {
  const tryInject = () => {
    const menu = TOP_DOC.getElementById('extensionsMenu');
    if (!menu) return false;
    if (TOP_DOC.getElementById('mh-wand-entry')) return true;

    const item = TOP_DOC.createElement('div');
    item.id = 'mh-wand-entry';
    item.className = 'list-group-item flex-container flexGap5 interactable';
    item.style.cssText = 'cursor:pointer;';
    item.innerHTML = `
      <div class="fa-solid fa-mask extensionsMenuExtensionButton" style="min-width:20px;text-align:center;"></div>
      <span id="mh-wand-toggle-text">${S.config.hidden ? '显示截图打码' : '隐藏截图打码'}</span>
    `;
    item.addEventListener('click', () => setHidden(!S.config.hidden));
    menu.appendChild(item);
    return true;
  };

  if (!tryInject()) {
    let tries = 0;
    const t = setInterval(() => {
      tries++;
      if (tryInject() || tries >= 10) clearInterval(t);
    }, 800);
  }
}

// ──────────────── 自动监听新消息 ────────────────
function startChatObserver() {
  if (window._mhChatObs) return;
  const obs = new MutationObserver(muts => {
    if (!S.masking) return;
    if (window._mhApplying) return;
    let need = false;
    for (const m of muts) {
      if (m.addedNodes.length || m.type === 'characterData') { need = true; break; }
    }
    if (need) {
      clearTimeout(window._mhDebounce);
      window._mhDebounce = setTimeout(() => {
        applyMasksAll();
      }, 120);
    }
  });
  const chat = TOP_DOC.getElementById('chat');
  if (chat) {
    obs.observe(chat, { childList: true, subtree: true, characterData: true });
    window._mhChatObs = obs;
  }
}

// ──────────────── UI 保活 ────────────────
function startRootObserver() {
  if (window._mhRootObs) return;
  window._mhRootObs = new MutationObserver(() => {
    if (!TOP_DOC.getElementById('mh-root')) { mountUI(); }
    if (!TOP_DOC.getElementById('mh-wand-entry')) injectWandMenu();
    if (!window._mhChatObs && TOP_DOC.getElementById('chat')) startChatObserver();
  });
  window._mhRootObs.observe(TOP_DOC.body, { childList: true, subtree: true });
}

// ──────────────── 监听酒馆事件，切换角色卡时刷新 ────────────────
function bindTavernEvents() {
  try {
    const ev = TOP.TavernHelper?.eventOn;
    const types = TOP.tavern_events || TOP.TavernHelper?.tavern_events;
    if (ev && types) {
      const refresh = () => {
        refreshAutoNames();
        renderAutoRows();
        reapply();
      };
      ['CHAT_CHANGED', 'CHARACTER_EDITED', 'MESSAGE_RECEIVED', 'MESSAGE_SENT', 'MESSAGE_EDITED'].forEach(name => {
        const evt = types[name];
        if (evt) ev(evt, refresh);
      });
    }
  } catch(e) { console.warn('[截图打码] 绑定酒馆事件失败:', e); }
}

// ──────────────── 启动 ────────────────
function init() {
  mountUI();
  startManualPersistence();
  startRootObserver();
  startChatObserver();
  bindTavernEvents();
  refreshAutoNames();
  renderAutoRows();
  // 延迟重试，兼容酒馆 context 加载较慢的情况
  [400, 1000, 2500].forEach(ms => {
    setTimeout(() => { renderAutoRows(); if (S.masking) reapply(); }, ms);
  });
  console.log('[截图打码] v1.8 ✅');
}

