    border-radius: 20px;
    padding: 16px;
    display: none;
    box-shadow: var(--mh-panel-shadow);
    color: var(--mh-text);
    transition: background 0.3s, border-color 0.3s, color 0.3s;
    scrollbar-width: thin;
    scrollbar-color: var(--mh-btn-border) transparent;
  }
  #mh-panel::-webkit-scrollbar { width: 4px; }
  #mh-panel::-webkit-scrollbar-thumb { background: var(--mh-btn-border); border-radius: 2px; }
  #mh-panel.open { display: block !important; }
  #mh-panel.above { bottom: 66px; }
  #mh-panel.below { top: 66px; }
  #mh-panel.right { right: 0; }
  #mh-panel.left { left: 0; }
  @media (max-width: 600px) {
    #mh-panel.open {
      position: fixed !important;
      left: 50vw !important;
      top: 50vh !important;
      right: auto !important;
      bottom: auto !important;
      transform: translate(-50%, -50%);
      width: min(340px, calc(100vw - 24px));
      box-sizing: border-box;
      max-height: min(78vh, calc(100dvh - 24px));
      z-index: 2147483647;
      touch-action: pan-y;
    }
  }

  .mh-title {
    font-size: 12px;
    color: var(--mh-accent);
    letter-spacing: .1em;
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  .mh-title-icon { display: flex; align-items: center; gap: 8px; color: var(--mh-accent2); }
  .mh-close { cursor: pointer; color: var(--mh-text-dim); display: flex; align-items: center; padding: 4px; border-radius: 6px; transition: all .15s; }
  .mh-close:hover { color: var(--mh-accent); background: var(--mh-btn-hover-bg); }

  .mh-tabs {
    display: flex; gap: 4px; margin-bottom: 12px;
    background: var(--mh-tab-bg); border-radius: 10px; padding: 3px;
  }
  .mh-tab {
    flex: 1; font-size: 11px; text-align: center;
    padding: 5px 0; border-radius: 7px; cursor: pointer;
    color: var(--mh-text-dim); transition: all .2s;
  }
  .mh-tab.on { background: var(--mh-tab-active); color: var(--mh-accent); }
  .mh-page { display: none; } .mh-page.on { display: block; }

  /* 大按钮 */
  .mh-big-btn {
    width: 100%; padding: 14px 0;
    background: var(--mh-btn-bg);
    border: 1px solid var(--mh-btn-border);
    border-radius: 12px;
    color: var(--mh-text-mute);
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all .25s;
    margin-bottom: 10px;
    letter-spacing: 0.05em;
  }
  .mh-big-btn:hover { background: var(--mh-btn-hover-bg); }
  .mh-big-btn.on {
    background: linear-gradient(135deg, rgba(167,139,250,0.4), rgba(244,114,182,0.35));
    border-color: rgba(244,114,182,0.5);
    color: #fff;
    box-shadow: 0 4px 16px rgba(244,114,182,0.25);
  }
  .mh-big-btn:active { transform: scale(0.98); }

  .mh-stats {
    text-align: center;
    font-size: 10px;
    font-family: monospace;
    color: var(--mh-text-dim);
    padding: 8px;
    background: var(--mh-card-bg);
    border: 1px solid var(--mh-card-border);
    border-radius: 8px;
    margin-bottom: 10px;
  }
  .mh-stats.on { color: var(--mh-accent); }

  .mh-hint {
    font-size: 10px;
    color: var(--mh-text-dim);
    line-height: 1.7;
    padding: 8px 10px;
    background: var(--mh-hint-bg);
    border-radius: 8px;
  }
  .mh-hint code {
    background: var(--mh-card-bg);
    padding: 1px 5px;
    border-radius: 3px;
    color: var(--mh-accent);
    font-size: 9px;
  }

  /* 区段 */
  .mh-section { margin-bottom: 14px; }
  .mh-section-title {
    font-size: 11px;
    color: var(--mh-accent);
    margin-bottom: 6px;
    padding-bottom: 4px;
    border-bottom: 1px solid var(--mh-card-border);
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  /* 自动检测行 */
  .mh-auto-row {
    display: flex; align-items: center; gap: 6px;
    padding: 6px 4px;
    border-radius: 8px;
  }
  .mh-name-info {
    flex: 1;
    min-width: 0;
  }
  .mh-name-label {
    font-size: 9px;
    color: var(--mh-text-dim);
    font-family: monospace;
  }
  .mh-name-value {
    font-size: 11px;
    color: var(--mh-text);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .mh-name-value i { color: var(--mh-text-faint); font-style: italic; }

  /* 名字列表项 */
  .mh-name-list {
    max-height: 180px;
    overflow-y: auto;
    margin-top: 6px;
    scrollbar-width: thin;
  }
  .mh-name-list::-webkit-scrollbar { width: 3px; }
  .mh-name-list::-webkit-scrollbar-thumb {
    background: var(--mh-btn-border); border-radius: 2px;
  }
  .mh-name-item {
    display: flex; align-items: center; gap: 5px;
    padding: 5px 4px;
    border-radius: 6px;
    margin-bottom: 3px;
    transition: background .1s;
  }
  .mh-name-item:hover { background: var(--mh-btn-hover-bg); }
  .mh-item-word {
    flex: 1; min-width: 0;
    font-size: 11px;
    color: var(--mh-text);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .mh-empty {
    text-align: center;
    color: var(--mh-text-faint);
    font-size: 10px;
    padding: 14px 0;
    font-family: monospace;
  }

  /* 迷你开关 */
  .mh-tog-wrap {
    position: relative;
    width: 28px; height: 16px;
    cursor: pointer;
    flex-shrink: 0;
    display: inline-block;
  }
  .mh-tog-wrap input { opacity: 0; width: 100%; height: 100%; position: absolute; cursor: pointer; margin: 0; }
  .mh-tog-mini {
    position: absolute; inset: 0;
    background: var(--mh-btn-bg);
    border: 1px solid var(--mh-btn-border);
    border-radius: 8px;
    transition: all .2s;
  }
  .mh-tog-mini::after {
    content: '';
    position: absolute; top: 1px; left: 1px;
    width: 12px; height: 12px;
    background: #fff;
    border-radius: 50%;
    transition: transform .2s;
    box-shadow: 0 1px 2px rgba(0,0,0,0.2);
  }
  .mh-tog-wrap input:checked ~ .mh-tog-mini {
    background: rgba(167,139,250,0.4);
    border-color: rgba(167,139,250,0.5);
  }
  .mh-tog-wrap input:checked ~ .mh-tog-mini::after { transform: translateX(12px); }

  /* 输入和选择 */
  .mh-inp {
    flex: 1; min-width: 0;
    background: var(--mh-input-bg);
    border: 1px solid var(--mh-btn-border);
    border-radius: 8px;
    color: var(--mh-text);
    font-size: 11px;
    padding: 5px 8px;
    outline: none;
    transition: border-color .2s;
  }
  .mh-inp:focus { border-color: rgba(167,139,250,0.5); }
  .mh-inp::placeholder { color: var(--mh-text-faint); }

  .mh-select {
    background: var(--mh-input-bg);
    border: 1px solid var(--mh-btn-border);
    border-radius: 8px;
    color: var(--mh-text);
    font-size: 10px;
    padding: 4px 6px;
    outline: none;
    cursor: pointer;
    flex-shrink: 0;
    max-width: 80px;
  }

  /* 按钮 */
  .mh-mini-btn {
    background: rgba(167,139,250,0.2);
    border: 1px solid rgba(167,139,250,0.35);
    border-radius: 8px;
    color: var(--mh-accent);
    font-size: 10px;
    padding: 4px 8px;
    cursor: pointer;
    transition: all .15s;
    display: inline-flex;
    align-items: center;
    gap: 4px;
  }
  .mh-remember {
    flex: 0 0 22px; width: 22px; height: 22px; padding: 0;
    border: 0; border-radius: 5px; background: transparent;
    color: var(--mh-text); font-size: 20px; line-height: 20px;
    cursor: pointer;
  }
  .mh-remember:hover:not(:disabled) { background: var(--mh-btn-hover-bg); }
  .mh-remember:disabled { opacity: .3; cursor: default; }
  .mh-mini-btn:hover { background: rgba(167,139,250,0.3); }
  .mh-mini-btn:disabled { opacity: .5; cursor: wait; }

  .mh-add-row {
    display: flex; gap: 5px; margin-bottom: 4px;
  }

  .mh-del-btn {
    background: none; border: none;
    color: var(--mh-text-dim);
    cursor: pointer; padding: 2px;
    display: flex; align-items: center;
    border-radius: 4px;
    transition: color .15s;
    flex-shrink: 0;
  }
  .mh-del-btn:hover { color: var(--mh-danger); }

  /* 设置行 */
  .mh-set-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 0;
    border-top: 1px solid var(--mh-card-border);
    font-size: 11px;
    color: var(--mh-text-mute);
    gap: 8px;
  }
  .mh-set-row:first-child { border-top: none; }

  .mh-theme-seg {
    display: flex;
    background: var(--mh-tab-bg);
    border-radius: 8px;
    padding: 2px;
  }
  .mh-theme-opt {
    padding: 4px 10px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 11px;
    display: flex;
    align-items: center;
    gap: 4px;
    color: var(--mh-text-dim);
    transition: all .2s;
  }
  .mh-theme-opt.on { background: var(--mh-tab-active); color: var(--mh-accent); }

  /* ───────────────── 打码样式（消息内 span） ───────────────── */
  .mh-mask {
    display: inline;
    padding: 0 !important;
    margin: 0 !important;
    border-radius: 0;
    transition: filter .15s;
  }
  .mh-mask[data-style="blur"] {
    filter: blur(5px);
    background: transparent !important;
    padding: 0;
  }
  .mh-mask[data-style="black"] {
    background: #000 !important;
    color: #000 !important;
    border-radius: 3px;
    padding: 0 2px;
  }
  .mh-mask[data-style="mosaic"] {
    background-image:
      linear-gradient(45deg, #888 25%, transparent 25%),
      linear-gradient(-45deg, #888 25%, transparent 25%),
      linear-gradient(45deg, transparent 75%, #888 75%),
      linear-gradient(-45deg, transparent 75%, #aaa 75%);
    background-size: 6px 6px;
    background-position: 0 0, 0 3px, 3px -3px, -3px 0;
    color: transparent !important;
    border-radius: 3px;
    padding: 0 2px;
  }
  .mh-mask[data-style="text"], .mh-mask[data-style="emoji"] {
    background: transparent !important;
    color: inherit;
    padding: 0 !important;
    margin: 0 !important;
    border-radius: 0;
  }
`;

// ──────────────── 启动 ────────────────
init();
